Use a count to distinguish full from empty: the invariant is 0 ≤ count ≤ 17, with tail = (head + count) modulo 17. When head equals tail, count is either 0 for empty or 17 for full; rejected operations leave the queue unchanged. Compile with C++17 and assertions enabled, for example: g++ -std=c++17 fifo.cpp -o fifo && ./fifo.

```cpp
#include <array>
#include <cassert>
#include <cstddef>

class BoundedFifo {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) {
            return false;
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) {
            return false;
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFifo queue;
    int value = -1;

    // Empty pop fails and leaves the output unchanged.
    assert(!queue.pop(value));
    assert(value == -1);
    assert(queue.empty());

    // Every slot is usable, including the seventeenth.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());

    // The eighteenth insertion is rejected.
    assert(!queue.push(999));
    assert(queue.size() == 17);

    // Verify rejection preserved every element and FIFO order.
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Leave three elements, then fill across the array boundary.
    for (int i = 0; i < 10; ++i) {
        assert(queue.push(i));
    }
    for (int i = 0; i < 7; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 10; i < 24; ++i) {
        assert(queue.push(i));
    }
    assert(queue.full());
    assert(!queue.push(24));
    assert(queue.size() == 17);

    // Draining also crosses the boundary, preserving FIFO order.
    for (int i = 7; i < 24; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));
    return 0;
}
```

The lower median is 4. Copy the input before using `std::nth_element`, so the caller’s array remains unchanged; reject empty input with `std::invalid_argument`.

For n > 0, select zero-based index k = (n − 1) / 2 using integer division. If n = 2m + 1, k = m, the middle element; if n = 2m, k = m − 1, the lower of the two middle elements. `std::nth_element` places at k the value that would occupy that index after sorting, including when values repeat.

Compile and run with assertions enabled: `g++ -std=c++17 median.cpp -o median && ./median`.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <stdexcept>
#include <vector>

int lowerMedian(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lowerMedian requires nonempty input");
    }

    std::vector<int> copy = input;
    const std::size_t k = (copy.size() - 1) / 2;
    auto selected = copy.begin() +
        static_cast<std::vector<int>::difference_type>(k);
    std::nth_element(copy.begin(), selected, copy.end());
    return *selected;
}

int main() {
    // Duplicates and the supplied even-sized input:
    // sorted order is 1, 2, 4, 4, 7, 9.
    const std::vector<int> duplicates{9, 1, 4, 4, 7, 2};
    const auto original = duplicates;
    assert(lowerMedian(duplicates) == 4);
    assert(duplicates == original);

    // Odd size: sorted order is 1, 2, 5, 8, 9.
    const std::vector<int> odd{8, 1, 5, 2, 9};
    const auto oddOriginal = odd;
    assert(lowerMedian(odd) == 5);
    assert(odd == oddOriginal);

    // Distinct middle values verify lower, not upper, median.
    const std::vector<int> even{10, 2, 8, 4};
    const auto evenOriginal = even;
    assert(lowerMedian(even) == 4);
    assert(even == evenOriginal);

    const std::vector<int> singleton{42};
    assert(lowerMedian(singleton) == 42);
    assert(singleton == std::vector<int>{42});

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lowerMedian(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());
    return 0;
}
```

No. A successful retry can store a stale desired value and lose an increment.

Concrete execution, starting at 0:
1. Thread A loads `expected = 0` and computes `desired = 1`.
2. Thread B successfully increments the counter from 0 to 1.
3. A compares against 0: it fails, overwriting `expected` with 1, but leaving `desired = 1`.
4. A retries, comparing against 1 and storing 1. It succeeds, yet the final count is 1 instead of 2.

Recompute `desired` on every attempt. A spurious failure also retries safely, whether or not `expected` changes. Relaxed ordering suffices for this counter alone; successful compare-exchange operations are its increment linearization points. This test stays below the unsigned overflow limit.

Compile with `g++ -std=c++17 -O2 -pthread counter.cpp -o counter` and run `./counter`, with assertions enabled.

```cpp
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure updates expected to the observed value.
        // Recompute desired above, including after spurious failure.
    }
}

int main() {
    constexpr unsigned threadCount = 4;
    constexpr std::uint64_t incrementsPerThread = 100000;
    constexpr std::uint64_t expectedTotal =
        threadCount * incrementsPerThread;

    std::atomic<std::uint64_t> counter{0};
    std::atomic<bool> start{false};
    std::vector<std::thread> workers;
    workers.reserve(threadCount);

    for (unsigned t = 0; t < threadCount; ++t) {
        workers.emplace_back([&] {
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            for (std::uint64_t i = 0; i < incrementsPerThread; ++i) {
                increment(counter);
            }
        });
    }

    start.store(true, std::memory_order_release);
    for (auto& worker : workers) {
        worker.join();
    }

    const auto actual = counter.load(std::memory_order_relaxed);
    assert(actual == expectedTotal);
    std::cout << "Final count: " << actual << '\n';
    return 0;
}
```
